// Procesar comandos del dueño: /tomar y /bot
// También guarda los mensajes del dueño en la memoria para que el bot los recuerde
const staticData = $getWorkflowStaticData('global');
if (!staticData.humanTakeover) staticData.humanTakeover = {};
if (!staticData.humanMessages) staticData.humanMessages = {};

// Extraer datos del mensaje del dueño (echo)
const echoData = $json.body.whatsappInboundMessage || $json.body;
const toPhone = echoData?.to || echoData?.customerProfile?.waId || '';
const messageText = String(echoData?.text?.body || '').trim();
const messageTextLower = messageText.toLowerCase();

if (!toPhone) return [{ json: { action: 'none', reason: 'no_phone' } }];

// Detectar comandos
if (messageTextLower === '/tomar' || messageTextLower === '/humano') {
  staticData.humanTakeover[toPhone] = { active: true, since: Date.now() };
  return [{ json: { action: 'takeover', phone: toPhone, message: '🙋 Chat tomado por humano. El bot está en silencio para este cliente.' } }];
}

if (messageTextLower === '/bot' || messageTextLower === '/liberar') {
  delete staticData.humanTakeover[toPhone];
  return [{ json: { action: 'release', phone: toPhone, message: '🤖 Bot activado. El bot retomó el control de este chat.' } }];
}

// GUARDAR MENSAJE DEL DUEÑO para que el bot lo recuerde después
// Este mensaje se agregará al historial de Redis
if (messageText && !messageTextLower.startsWith('/')) {
  // Guardar mensaje para sincronizar con Redis después
  if (!staticData.humanMessages[toPhone]) staticData.humanMessages[toPhone] = [];
  staticData.humanMessages[toPhone].push({
    role: 'assistant', // El dueño actúa como el "asistente" desde la perspectiva del cliente
    content: messageText,
    timestamp: Date.now()
  });
  // Mantener solo últimos 20 mensajes del humano por cliente
  if (staticData.humanMessages[toPhone].length > 20) {
    staticData.humanMessages[toPhone] = staticData.humanMessages[toPhone].slice(-20);
  }
  return [{ json: { action: 'save_message', phone: toPhone, message: messageText, savedToMemory: true } }];
}

return [{ json: { action: 'none', reason: 'empty_or_command' } }];

// Deduplicación + Verificación de Human Takeover
const messageId = $input.first().json.messageId;
const phoneNumber = $input.first().json.phoneNumber;
const staticData = $getWorkflowStaticData('global');
const now = Date.now();

// Inicializar estructuras
if (!staticData.processedIds) staticData.processedIds = {};
if (!staticData.humanTakeover) staticData.humanTakeover = {};

// Limpiar IDs antiguos (más de 1 hora)
for (const id in staticData.processedIds) {
  if (now - staticData.processedIds[id] > 3600000) {
    delete staticData.processedIds[id];
  }
}

// Verificar duplicados
if (staticData.processedIds[messageId]) return [];
staticData.processedIds[messageId] = now;

// VERIFICAR SI EL CHAT ESTÁ TOMADO POR HUMANO
// Si está tomado, el bot NO responde (silencio)
if (staticData.humanTakeover[phoneNumber]?.active) {
  // Chat tomado por humano - bot en silencio
  return [];
}

// Chat libre - bot puede responder
return [{ json: $input.first().json }];

// Combine Messages - Detectar acciones interactivas con prioridad
const messages = $json.Mensaje || [];

// Parsear todos los mensajes y filtrar solo los del buffer (que tienen phoneNumber)
const parsed = [];
let phoneNumber = '';
let contactName = '';
let phoneNumberId = '';
let businessPhone = '';
let isFromAudio = false;

for (const m of messages) {
  try {
    const p = JSON.parse(m);
    // Solo considerar mensajes del buffer (tienen phoneNumber y message)
    if (p.phoneNumber && p.message !== undefined) {
      parsed.push(p);
      // Guardar datos del usuario del primer mensaje válido
      if (!phoneNumber) {
        phoneNumber = p.phoneNumber;
        contactName = p.contactName || '';
        phoneNumberId = p.phoneNumberId || '';
        businessPhone = p.businessPhone || '';
      }
      // Si alguno fue de audio
      if (p.isFromAudio) isFromAudio = true;
    }
  } catch(e) {}
}

// Buscar si hay alguna acción interactiva (prioridad al ÚLTIMO mensaje con acción)
const actionPrefixes = ['svc_', 'day_', 'time_', 'cancel_confirm_', 'cancel_keep'];
let interactiveAction = null;

for (let i = parsed.length - 1; i >= 0; i--) {
  const msg = parsed[i].message || '';
  for (const prefix of actionPrefixes) {
    if (msg.startsWith(prefix) || msg === prefix.replace('_', '')) {
      interactiveAction = msg;
      break;
    }
  }
  if (interactiveAction) break;
}

// Si hay acción interactiva, usar SOLO esa acción
// Si no hay, concatenar todos los mensajes para la IA
const textContent = interactiveAction || parsed.map(p => p.message).join(' ');

return {
  json: {
    textContent,
    phoneNumber,
    contactName,
    phoneNumberId,
    businessPhone,
    isFromAudio,
    hasInteractiveAction: !!interactiveAction
  }
};

// Construir listas de servicios para WhatsApp (máx 10 por mensaje)
const rows = $input.all().map(i => i.json).filter(r => r.id && r.nombre && r.duracion_min);
const maxPerMessage = 10;
const totalServices = rows.length;
const totalMessages = Math.ceil(totalServices / maxPerMessage);

// Dividir en chunks de 10
const chunks = [];
for (let i = 0; i < totalServices; i += maxPerMessage) {
  chunks.push(rows.slice(i, i + maxPerMessage));
}

// Retornar un item por cada chunk
return chunks.map((chunk, index) => {
  const start = index * maxPerMessage + 1;
  const end = Math.min((index + 1) * maxPerMessage, totalServices);

  const listRows = chunk.map(r => ({
    id: `svc_${r.id}`,
    title: String(r.nombre).slice(0, 24),
    description: `${r.duracion_min} min - ${r.precio || 'Consultar'}`.slice(0, 72),
  }));

  const headerText = totalMessages === 1 
    ? '🛍️ Servicios' 
    : `🛍️ Servicios (${index + 1}/${totalMessages})`;

  const bodyText = index === 0
    ? `Selecciona el servicio que deseas agendar (${totalServices} disponibles):`
    : `Más servicios disponibles (${start}-${end} de ${totalServices}):`;

  return { json: { services: rows, listRows, headerText, bodyText, chunkIndex: index, totalChunks: totalMessages } };
});

// Guardar servicio seleccionado (duración) en staticData por teléfono
const payload = $('Combine Messages').first().json;
const selectedId = String(payload.textContent || '').replace('svc_', '');
const services = $input.all().map(i => i.json);
const svc = services.find(s => String(s.id) === String(selectedId));

if (!svc) {
  // Servicio no encontrado - enviar mensaje de error
  return [{ json: { ...payload, error: 'SERVICE_NOT_FOUND', errorMessage: 'Lo siento, no encontré ese servicio. Por favor selecciona uno de la lista.' } }];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.selectedServiceByPhone) staticData.selectedServiceByPhone = {};
staticData.selectedServiceByPhone[payload.phoneNumber] = { 
  id: String(svc.id), 
  nombre: svc.nombre, 
  duracion_min: Number(svc.duracion_min || 30),
  precio: svc.precio || '',
  selectedAt: Date.now()
};

return [{ json: { ...payload, selectedService: staticData.selectedServiceByPhone[payload.phoneNumber] } }];

// Generar próximos 7 días hábiles con validación de servicio
const { phoneNumber, phoneNumberId, businessPhone, contactName, selectedService, error } = $json;

// Si hubo error en selección de servicio, retornar para manejar
if (error) {
  return [{ json: { phoneNumber, phoneNumberId, businessPhone, error, errorMessage: $json.errorMessage } }];
}

const diasHabiles = [1,2,3,4,5]; // Lun-Vie
const availableDays = [];
let date = new Date();
date.setDate(date.getDate() + 1); // Empezar desde mañana

while (availableDays.length < 7) {
  if (diasHabiles.includes(date.getDay())) {
    const dateStr = date.toISOString().split('T')[0];
    const dayNames = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
    const display = `${dayNames[date.getDay()]} ${date.getDate()}/${date.getMonth()+1}`;
    availableDays.push({ date: dateStr, display, btnId: `day_${dateStr}` });
  }
  date.setDate(date.getDate()+1);
}

return [{ json: { phoneNumber, phoneNumberId, businessPhone, contactName, availableDays, selectedService } }];

