// Preparar cancelación - filtrar y mostrar TODAS las citas del usuario
const { phoneNumber, phoneNumberId } = $('Parse Actions').first().json;
const phoneClean = String(phoneNumber).replace('+', '').replace(/\s/g, '');

// Filtrar citas: mismo teléfono Y estado Confirmado
// Convertir ambos a string para comparación correcta
const appointments = $input.all().filter(item => {
  const apt = item.json;
  const aptPhone = String(apt.telefono).replace(/\s/g, '');
  return aptPhone === phoneClean && apt.estado === 'Confirmado' && apt.id;
});

if (appointments.length === 0) {
  return [{ json: { phoneNumber, phoneNumberId, hasAppointment: false, appointmentCount: 0, message: 'No encontré citas activas asociadas a tu número.' } }];
}

// Construir lista de citas para el mensaje
const citasList = appointments.map((item, idx) => {
  const apt = item.json;
  return `${idx + 1}. 📅 ${apt.fecha} | 🕐 ${apt.hora}-${apt.hora_fin} | 🛍️ ${apt.servicio}`;
}).join('\n');

// Construir rows para la lista interactiva (max 10)
const listRows = appointments.slice(0, 10).map(item => {
  const apt = item.json;
  return {
    id: `cancel_confirm_${apt.id}`,
    title: `${apt.fecha} ${apt.hora}`.slice(0, 24),
    description: `${apt.servicio} (${apt.hora}-${apt.hora_fin})`.slice(0, 72)
  };
});

const message = appointments.length === 1 
  ? `Encontré tu cita:\n\n📅 ${appointments[0].json.fecha}\n🕐 ${appointments[0].json.hora} - ${appointments[0].json.hora_fin}\n🛍️ ${appointments[0].json.servicio}\n\n¿Confirmas que deseas cancelarla?`
  : `Encontré ${appointments.length} citas activas:\n\n${citasList}\n\nSelecciona la cita que deseas cancelar:`;

return [{ 
  json: { 
    phoneNumber, 
    phoneNumberId, 
    hasAppointment: true, 
    appointmentCount: appointments.length,
    appointmentId: appointments[0].json.id,
    listRows,
    message
  } 
}];

