// Preparar input del chat con contexto de mensajes del humano
const input = $json;
const staticData = $getWorkflowStaticData('global');
const phoneNumber = input.phoneNumber;

// Obtener mensajes recientes del humano (dueño) para este cliente
let humanContext = '';
if (staticData.humanMessages && staticData.humanMessages[phoneNumber]) {
  const humanMsgs = staticData.humanMessages[phoneNumber];
  // Solo incluir mensajes de las últimas 24 horas como contexto adicional
  const oneDayAgo = Date.now() - (24 * 60 * 60 * 1000);
  const recentHumanMsgs = humanMsgs.filter(m => m.timestamp > oneDayAgo);
  if (recentHumanMsgs.length > 0) {
    humanContext = '\n\n[CONTEXTO: El dueño del negocio respondió directamente a este cliente con los siguientes mensajes recientes:]\n' + 
      recentHumanMsgs.map(m => `- "${m.content}"`).join('\n') + '\n[FIN CONTEXTO]\n\n';
  }
}

return [{
  json: {
    chatInput: humanContext + input.textContent,
    phoneNumber: phoneNumber,
    phoneNumberId: input.phoneNumberId,
    contactName: input.contactName,
    isFromAudio: input.isFromAudio || false,
    hasHumanContext: humanContext.length > 0
  }
}];

// Convertir configuración de Google Sheets a objeto key-value
const config = {};

// Leer configuración del bot (Configuracion_Bot)
const botConfigRows = $input.all();
botConfigRows.forEach(item => {
  const parametro = item.json.parametro;
  const valor = item.json.valor;
  if (parametro && valor !== undefined) {
    config[parametro] = valor;
  }
});

// Obtener datos del chat del nodo anterior
const chatData = $('Prepare Chat Input').first().json;

return [{
  json: {
    ...chatData,
    config: config
  }
}];

// Parse actions y detectar si debe responder con audio
const output = $json.output || '';
const base = $('Prepare Chat Input').first().json;
const isFromAudio = base.isFromAudio || false;

let action = 'send_text';
let clean = output;

// Detectar acciones especiales
if (output.includes('<<ACTION:SHOW_SERVICES>>')) {
  action = 'show_services';
  clean = output.replace(/<<ACTION:SHOW_SERVICES>>/g,'').trim();
} else if (output.includes('<<ACTION:CANCEL_APPOINTMENT>>')) {
  action = 'cancel_appointment';
  clean = output.replace(/<<ACTION:CANCEL_APPOINTMENT>>/g,'').trim();
} else if (output.includes('<<ACTION:ESCALATE_TO_HUMAN>>')) {
  action = 'escalate_to_human';
  clean = output.replace(/<<ACTION:ESCALATE_TO_HUMAN>>/g,'').trim();
} else if (isFromAudio) {
  // Si el mensaje original fue audio y no hay acción especial, responder con audio
  action = 'send_audio';
}

return { json: { action, output: clean, isFromAudio, ...base } };

// Preparar audio con mime type correcto para WhatsApp
const item = $input.first();
const originalBinary = item.binary.data;

return [{
  json: {
    phoneNumber: $('Parse Actions').first().json.phoneNumber,
    phoneNumberId: $('Parse Actions').first().json.phoneNumberId,
    output: $('Parse Actions').first().json.output
  },
  binary: {
    data: {
      ...originalBinary,
      mimeType: 'audio/mpeg',
      fileName: 'response.mp3',
      fileExtension: 'mp3'
    }
  }
}];
